     children: Array<[string, unknown]>;
   };

   let expandedPaths: Record<string, boolean> = $state({});

   const isRecord = (input: unknown): input is Record<string, unknown> =>
     typeof input === "object" && input !== null && !Array.isArray(input);
   const isContainer = (input: unknown): input is Record<string, unknown> | unknown[] =>
     typeof input === "object" && input !== null;
   const isEmpty = (input: unknown): boolean =>
     input === undefined
     || input === null
     || (typeof input === "string" && input.trim() === "")
     || (isRecord(input) && Object.keys(input).length === 0);
