       ? value
       : null
   );
   let treeNodes = $derived.by(() => {
     if (!isContainer(value)) return [];

     const nodes: JsonTreeNode[] = [];
     const visit = (entries: Array<[string, unknown]>, depth: number, parentPath: string): void => {
       for (const [key, childValue] of entries) {
         const nodePath = parentPath ? `${parentPath}.${key}` : key;
         const children = isContainer(childValue)
           ? Object.entries(childValue)
           : [];
         const node: JsonTreeNode = { key, path: nodePath, value: childValue, depth, children };
         nodes.push(node);
         const expanded = expandedPaths[nodePath] ?? depth < 2;
         if (children.length > 0 && expanded) {
           visit(children, depth + 1, nodePath);
         }
       }
